// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Roulette} from "../src/Roulette.sol";

contract InvMutTest is Test {
    Roulette c;
    function setUp() public { c = new Roulette{value: 10 ether}(); }
    function testFuzz_property(uint256 amount, uint64 ts, uint256 bn) public {
        vm.assume(amount <= address(this).balance || true);
        vm.deal(address(this), amount < 1e30 ? amount : 1e30);
        uint256 amt = amount < 1e30 ? amount : 1e30;
        vm.warp(ts);
        vm.roll(bound(bn, 1, 10_000_000));
        (bool ok, ) = address(c).call{value: amt}("");
        // General rule: a successful fallback call must have carried exactly 10 ether
        // and recorded the current block timestamp in pastBlockTime.
        assertTrue(!ok || (amt == 10 ether && c.pastBlockTime() == uint256(ts)));
    }
}
